private val EXNESS_KE_SERVER_FALLBACK = listOf(Mt5Server("EXNESS-KE:ExnessKE-MT5Real10", "Exness (KE)", "ExnessKE-MT5Real10", "real"), Mt5Server("EXNESS-KE:ExnessKE-MT5Real21", "Exness (KE)", "ExnessKE-MT5Real21", "real"), Mt5Server("EXNESS-KE:ExnessKE-MT5Real4", "Exness (KE)", "ExnessKE-MT5Real4", "real"), Mt5Server("EXNESS-KE:ExnessKE-MT5Real9", "Exness (KE)", "ExnessKE-MT5Real9", "real"), Mt5Server("EXNESS-KE:ExnessKE-MT5Trial10", "Exness (KE)", "ExnessKE-MT5Trial10", "demo"), Mt5Server("EXNESS-KE:ExnessKE-MT5Trial4", "Exness (KE)", "ExnessKE-MT5Trial4", "demo"), Mt5Server("EXNESS-KE:ExnessKE-MT5Trial9", "Exness (KE)", "ExnessKE-MT5Trial9", "demo"))
private val KENYA_BROKER_ALIASES = setOf("fxpesa", "egmsecurities", "scopemarkets", "scfm", "pepperstone", "pepperstonemarketskenya", "exinity", "fxtm", "hfm", "hfmarkets", "hfmarket", "hfm investments", "windsor", "windsormarkets", "exness", "exnesske", "ingot", "ingotke", "admirals", "admiralske", "fpmarkets", "icmarkets", "xm", "tpxm")
private fun normalizeBroker(value: String): String = value.lowercase().replace(Regex("[^a-z0-9]"), "")
private fun isKenyaQuery(value: String): Boolean { val q = normalizeBroker(value); return q == "ke" || q.contains("kenya") || q.contains("kenyan") || q.contains("nairobi") }
private fun isHfmQuery(value: String): Boolean { val q = normalizeBroker(value); return q.contains("hfm") || q.contains("hfmarket") || q.contains("hotforex") }
private fun isExnessQuery(value: String): Boolean = normalizeBroker(value).contains("exness")
private fun isKenyaBroker(server: Mt5Server): Boolean { val broker = normalizeBroker(server.brokerName); val name = normalizeBroker(server.serverName); return KENYA_BROKER_ALIASES.any { alias -> broker.contains(normalizeBroker(alias)) } || broker.contains("kenya") || name.contains("marketske") || name.contains("exnesske") }
private fun serverMatches(query: String, server: Mt5Server): Boolean { val q = normalizeBroker(query); if (q.isBlank()) return true; val broker = normalizeBroker(server.brokerName); val name = normalizeBroker(server.serverName); if (isKenyaQuery(query)) return isKenyaBroker(server); if (isHfmQuery(query)) return broker.contains("hfm") || broker.contains("hfmarket") || name.contains("hfmarket") || name.contains("hotforex"); if (isExnessQuery(query)) return broker.contains("exness") || name.contains("exness"); return broker.contains(q) || q.contains(broker) || name.contains(q) }
private fun serverScore(query: String, server: Mt5Server): Int { val q = normalizeBroker(query); val broker = normalizeBroker(server.brokerName); val name = normalizeBroker(server.serverName); if (isKenyaQuery(query)) return when { name.contains("hfmarketske") || name.contains("exnesske") -> 120; broker.contains("kenya") -> 110; isKenyaBroker(server) -> 100; else -> 10 }; if (isHfmQuery(query)) return when { name.contains("hfmarketske") -> 120; broker == "hfm" -> 110; name.contains("hfmarketsglobal") -> 100; name.contains("hfmarketssa") -> 95; else -> 80 }; if (isExnessQuery(query)) return when { name.contains("exnesske") -> 120; broker.contains("exness") -> 110; else -> 80 }; if (broker == q) return 100; if (broker.startsWith(q)) return 90; if (broker.contains(q)) return 80; if (name.startsWith(q)) return 70; if (name.contains(q)) return 60; return 10 }

class BackendApiClient(private val http: OkHttpClient = OkHttpClient()) {
    private val base = BuildConfig.BACKEND_BASE_URL.trimEnd('/')
    suspend fun findServers(query: String): Result<List<Mt5Server>> = runCatching { withContext(Dispatchers.IO) { val q = query.trim(); if (q.length < 2) return@withContext emptyList(); val merged = LinkedHashMap<String, Mt5Server>(); coroutineScope { val backend = async { runCatching { parseServerResults(requestJson("GET", "/api/mt5/servers?q=${URLEncoder.encode(q, "UTF-8")}", null)) }.getOrDefault(emptyList()) }; val directory = async { runCatching { parseServerResults(requestRaw(PUBLIC_SERVER_DIRECTORY)) }.getOrDefault(emptyList()) }; backend.await().forEach { merged[serverKey(it)] = it }; directory.await().forEach { merged[serverKey(it)] = it } }; if (isHfmQuery(q) || isKenyaQuery(q)) HFM_SERVER_FALLBACK.forEach { merged[serverKey(it)] = it }; if (isExnessQuery(q) || isKenyaQuery(q)) EXNESS_KE_SERVER_FALLBACK.forEach { merged[serverKey(it)] = it }; merged.values.filter { serverMatches(q, it) }.sortedWith(compareByDescending<Mt5Server> { serverScore(q, it) }.thenBy { it.serverName.lowercase() }).take(100) } }
    suspend fun connect(login: String, password: String, server: String, broker: String): Result<BackendSession> = runCatching { val r = JSONObject(requestJson("POST", "/api/mt5/connect", JSONObject().apply { put("login", login); put("password", password); put("server", server); put("broker", broker); put("name", "Pips-life MT5 $login") }.toString())); BackendSession(r.getString("accountId"), r.getString("sessionToken"), r.optString("server", server)) }
    suspend fun liveState(session: BackendSession): Result<LiveState> = runCatching { val r = JSONObject(requestJson("GET", "/api/mt5/state?accountId=${URLEncoder.encode(session.accountId, "UTF-8")}", null, session.token)); val a = r.optJSONObject("account") ?: JSONObject(); LiveState(session.accountId, a.optString("login"), a.optString("server"), a.optString("connectionStatus"), a.optString("state"), a.optDouble("balance", Double.NaN), a.optDouble("equity", Double.NaN), a.optDouble("freeMargin", Double.NaN), a.optString("currency", ""), a.optString("name", ""), parsePositions(r.optJSONArray("positions") ?: JSONArray())) }
    suspend fun botStatus(session: BackendSession): Result<BotState> = runCatching { val r = JSONObject(requestJson("GET", "/api/bot/control?accountId=${URLEncoder.encode(session.accountId, "UTF-8")}", null, session.token)); BotState(r.optBoolean("configured", false), r.optString("state", "UNKNOWN"), r.optString("strategy", ""), r.optString("activity", "")) }
    suspend fun botCommand(session: BackendSession, action: String, strategy: String? = null): Result<BotState> = runCatching {
        val rawAction = action.trim()
        val requestedStrategy = strategy?.takeIf { it == "001" || it == "002" } ?: rawAction.removePrefix("select:").removePrefix("start:").takeIf { it == "001" || it == "002" }
        val normalizedAction = when {
            rawAction.startsWith("select:") -> "select"
            rawAction.startsWith("start:") -> "start"
            else -> rawAction
        }
        val r = JSONObject(requestJson("POST", "/api/bot/control", JSONObject().apply { put("action", normalizedAction); put("accountId", session.accountId); if (requestedStrategy != null) put("strategy", requestedStrategy) }.toString(), session.token))
        BotState(r.optBoolean("configured", true), r.optString("state", normalizedAction.uppercase()), r.optString("strategy", requestedStrategy ?: ""), r.optString("activity", "COMMAND ACCEPTED"))
    }
    private fun parseServerResults(text: String): List<Mt5Server> { val trimmed = text.trim(); if (trimmed.isBlank()) return emptyList(); val root = runCatching { JSONObject(trimmed) }.getOrNull(); val a = root?.optJSONArray("brokers") ?: root?.optJSONArray("data") ?: runCatching { JSONArray(trimmed) }.getOrNull() ?: return emptyList(); return buildList { for (i in 0 until a.length()) { val b = a.optJSONObject(i) ?: continue; val broker = b.optString("name").ifBlank { b.optString("broker").ifBlank { "Unknown broker" } }; val servers = b.optJSONArray("servers") ?: b.optJSONArray("serverList") ?: JSONArray(); for (j in 0 until servers.length()) { val s = servers.optJSONObject(j) ?: continue; val name = s.optString("name").ifBlank { s.optString("server") }.trim(); if (name.isNotBlank()) add(Mt5Server("${b.optString("id", broker)}:$name", broker, name, s.optString("type", "real"))) } } } }
    private fun serverKey(s: Mt5Server) = "${normalizeBroker(s.brokerName)}:${normalizeBroker(s.serverName)}"
    private fun parsePositions(a: JSONArray): List<LivePosition> = buildList { for (i in 0 until a.length()) { val p = a.getJSONObject(i); add(LivePosition(p.optString("symbol"), p.optString("type").removePrefix("POSITION_TYPE_").ifBlank { p.optString("side") }, p.optDouble("volume", 0.0), p.optDouble("openPrice", Double.NaN), p.optDouble("currentPrice", Double.NaN), p.optDoubleOrNull("stopLoss"), p.optDoubleOrNull("takeProfit"), p.optDouble("profit", Double.NaN))) } }
    private suspend fun requestRaw(url: String): String = withContext(Dispatchers.IO) { val request = Request.Builder().url(url).addHeader("Accept", "application/json").get().build(); http.newCall(request).execute().use { r -> val t = r.body?.string().orEmpty(); if (!r.isSuccessful) throw IllegalStateException("Server directory request failed (${r.code})"); t } }
    private suspend fun requestJson(method: String, path: String, body: String?, token: String? = null): String = withContext(Dispatchers.IO) { val b = Request.Builder().url(base + path).addHeader("Accept", "application/json"); if (token != null) b.addHeader("x-pipslife-session", token); if (body != null) b.method(method, body.toRequestBody("application/json".toMediaType())) else b.method(method, null); http.newCall(b.build()).execute().use { r -> val t = r.body?.string().orEmpty(); if (!r.isSuccessful) throw IllegalStateException(error(t, "Backend request failed (${r.code})")); t } }
    private fun error(b: String, f: String) = runCatching { JSONObject(b).optString("error").ifBlank { f } }.getOrDefault(f)
    private fun JSONObject.optDoubleOrNull(n: String): Double? = if (has(n) && !isNull(n)) optDouble(n).takeUnless { it.isNaN() } else null
}

data class BackendSession(val accountId: String, val token: String, val server: String)
data class LiveState(val accountId: String, val login: String, val server: String, val connectionStatus: String, val state: String, val balance: Double, val equity: Double, val freeMargin: Double, val currency: String, val userName: String, val positions: List<LivePosition>)
data class LivePosition(val symbol: String, val side: String, val volume: Double, val entry: Double, val current: Double, val stopLoss: Double?, val takeProfit: Double?, val profit: Double)
data class BotState(val configured: Boolean, val state: String, val strategy: String, val activity: String)
